package com.personal.meditation;
import org.junit.Test;import static org.junit.Assert.*;
public class SessionClockTest {
 @Test public void prepHasTwoShortPulsesThenLongAndBellAtThirty(){SessionClock c=new SessionClock();c.start(1000,600000);assertNull(c.poll(27999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(28000));assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(29000));assertEquals(SessionClock.Cue.LONG,c.poll(30000));assertEquals("preparing",c.phase(30999));assertEquals(SessionClock.Cue.START,c.poll(31000));assertEquals("meditating",c.phase(31000));assertEquals(600000,c.remaining(31000));}
 @Test public void tenMinutesHasExactlyThreeQuarterChimesAndOneEnd(){SessionClock c=new SessionClock();c.start(0,600000);assertEquals(SessionClock.Cue.START,c.poll(30000));assertNull(c.poll(179999));assertEquals(SessionClock.Cue.QUARTER_ONE,c.poll(180000));assertEquals(SessionClock.Cue.QUARTER_TWO,c.poll(330000));assertEquals(SessionClock.Cue.QUARTER_THREE,c.poll(480000));assertEquals(SessionClock.Cue.END,c.poll(630000));assertEquals("finished",c.phase(630000));assertEquals(0,c.remaining(630000));assertNull(c.poll(900000));}
 @Test public void pauseAndResumeKeepExactRemainingTimesAndDoNotRepeatCues(){SessionClock c=new SessionClock();c.start(0,60000);c.poll(27000);c.pause(27500);assertEquals("paused",c.phase(100000));assertEquals(2500,c.remaining(100000));assertNull(c.poll(100000));c.resume(100000);assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(100500));assertEquals(SessionClock.Cue.LONG,c.poll(101500));assertEquals(SessionClock.Cue.START,c.poll(102500));assertEquals(60000,c.remaining(102500));c.pause(110000);c.resume(210000);assertEquals(52500,c.remaining(210000));assertEquals(SessionClock.Cue.QUARTER_ONE,c.poll(217500));}
 @Test public void delayedRefreshDoesNotShiftDeadlinesOrBurstOldCues(){SessionClock c=new SessionClock();c.start(0,60000);assertEquals(SessionClock.Cue.START,c.poll(31000));assertEquals(59000,c.remaining(31000));assertEquals(SessionClock.Cue.QUARTER_TWO,c.poll(60000));assertNull(c.poll(60000));assertEquals(SessionClock.Cue.END,c.poll(90001));}
 @Test public void endResetAndNewSessionHaveNoStaleEvents(){SessionClock c=new SessionClock();c.start(0,60000);c.poll(90000);c.stop();assertEquals("idle",c.phase(100000));assertNull(c.poll(100000));c.start(100000,120000);assertEquals(30000,c.remaining(100000));assertNull(c.poll(126999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(127000));}
 @Test public void durationsAreBounded(){for(long ms:new long[]{0,59999,14400001})try{new SessionClock().start(0,ms);fail();}catch(IllegalArgumentException expected){}SessionClock c=new SessionClock();c.start(0,14400000);assertEquals(14400000,c.duration());}
 @Test public void schedulingTargetsCueDeadlinesInsteadOfAccumulatingPollDelays(){SessionClock c=new SessionClock();c.start(1000,600000);assertEquals(1000,c.nextDelay(1000));assertEquals(1,c.nextDelay(27999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(28000));assertEquals(750,c.nextDelay(28250));assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(29000));assertEquals(1,c.nextDelay(29999));assertEquals(SessionClock.Cue.LONG,c.poll(30000));assertEquals(SessionClock.Cue.START,c.poll(31000));assertEquals(1,c.nextDelay(180999));assertEquals(SessionClock.Cue.QUARTER_ONE,c.poll(181000));c.pause(181100);assertEquals(1000,c.nextDelay(999999));c.resume(1000000);assertEquals(1000,c.nextDelay(1000000));}
}
